R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
echo "== ktrev procs"; for p in $(pgrep -f "agent -p"); do d=$(readlink /proc/$p/cwd); echo "$p $d $(ps -o etime=,time= -p $p)"; done
find $R/sb_ktrev/work -newermt "-12 minutes" -type f | head -5; ls -la --time-style=+%TZ $R/sb_ktrev/cursor.log
mkdir -p $R/sb_mfrev; cp $R/sb_cursor_probe/AGENTS.md $R/sb_mfrev/AGENTS.md
echo  | base64 -d > $R/sb_mfrev/PROMPT.md
cd $R/sb_mfrev && tmux new-session -d -s sb_mfrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
sed -n 1,3p $R/sb_maskfail/out/SPLITS.md; grep -n -i -A3 "wrong.instance" $R/sb_maskfail/RULES.md | head -20
